import{_ as n,C as s,o as i,c as l,a2 as o,j as t,a,E as d}from"./chunks/framework.Dx-TCpNt.js";const y=JSON.parse('{"title":"FAQ & Troubleshooting","description":"Fix missing pages, unrecognized language folders, inaccurate panel detection, exports without images, lost source files and desktop data-directory problems.","frontmatter":{"description":"Fix missing pages, unrecognized language folders, inaccurate panel detection, exports without images, lost source files and desktop data-directory problems."},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1794745555000}'),h={name:"faq.md"};function p(c,e,g,u,m,f){const r=s("Badge");return i(),l("div",null,[e[6]||(e[6]=o('<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; Troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to &quot;FAQ &amp; Troubleshooting&quot;">​</a></h1><h2 id="the-library-is-empty" tabindex="-1">The library is empty <a class="header-anchor" href="#the-library-is-empty" aria-label="Permalink to &quot;The library is empty&quot;">​</a></h2><p><strong>Symptom:</strong> the sidebar says no volumes were found.</p><p>Check the folder shape under <code>raw/</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>raw/&lt;volume&gt;/&lt;language-dir&gt;/&lt;chapter&gt;/001.jpg</span></span></code></pre></div><p>Common causes:</p><ul><li>The volume folder exists but the language folder is not recognized. Use volume settings to map it, or rename it to <code>ja</code>, <code>zh</code> or <code>en</code> (aliases are listed in <a href="/KomaYomi-docs/guide/gallery">Library</a>).</li><li>The chapter folder is directly under the volume (<code>raw/&lt;volume&gt;/001.jpg</code>). A language directory is required.</li><li>The data directory in the desktop app points somewhere else. Press <code>Ctrl+Shift+D</code> to choose the correct folder, or set <code>MANGA_DATA_DIR</code>.</li></ul><h2 id="a-language-is-missing-on-one-page" tabindex="-1">A language is missing on one page <a class="header-anchor" href="#a-language-is-missing-on-one-page" aria-label="Permalink to &quot;A language is missing on one page&quot;">​</a></h2><p><strong>Symptom:</strong> a page shows only <code>JA</code> and <code>ZH</code>; <code>EN</code> is disabled.</p><p>Pages are paired by sorted index. If English has one fewer file in that chapter, the last page has no English image. The page warning names the missing language and page number. Add the file or remove the stray page.</p><p>If the counts match but the pairing is wrong, check filenames: a leading number that disagrees with sorted position triggers a warning. Rename files so natural sort matches the intended order.</p><h2 id="filenames-look-fine-but-pages-are-out-of-order" tabindex="-1">Filenames look fine but pages are out of order <a class="header-anchor" href="#filenames-look-fine-but-pages-are-out-of-order" aria-label="Permalink to &quot;Filenames look fine but pages are out of order&quot;">​</a></h2><p>Sorting is <strong>natural</strong>: digit runs compare numerically, so <code>2.jpg</code> comes before <code>10.jpg</code>. It is not byte-wise lexicographic. If a file has no leading number, it may sort before numbered files. Prefix pages consistently, e.g. <code>001.jpg</code>, <code>002.jpg</code>.</p><h2 id="panel-detection-is-inaccurate" tabindex="-1">Panel detection is inaccurate <a class="header-anchor" href="#panel-detection-is-inaccurate" aria-label="Permalink to &quot;Panel detection is inaccurate&quot;">​</a></h2><ul><li><strong>The left/right vertical strip is ignored.</strong> This is intentional: the narrow edge strip (typically <em>あらすじ</em> or an author note) is filtered so it does not become a false panel. Draw a legitimate edge panel manually.</li><li><strong>Splash pages</strong> often produce one big panel plus fragments. Select the fragments and <strong>Merge</strong>.</li><li><strong>Very small or very thin boxes</strong> are filtered as noise. Add them manually if they are real.</li><li><strong>WebP pages are not decoded</strong> for detection. Convert to JPEG/PNG if you need automatic detection.</li><li><strong>Fixed magazine layouts</strong> are better served by a <a href="/KomaYomi-docs/extending">layout template</a> than by detection.</li></ul><p>After correcting panels, avoid re-running auto detection unless you accept losing the manual boxes.</p><h2 id="exported-html-shows-no-images" tabindex="-1">Exported HTML shows no images <a class="header-anchor" href="#exported-html-shows-no-images" aria-label="Permalink to &quot;Exported HTML shows no images&quot;">​</a></h2><p><strong>Folder mode (default):</strong> the HTML references a sibling <code>&lt;name&gt;.files/</code> directory. Copy <strong>both</strong> the <code>.html</code> file and the <code>.files</code> folder, keeping their relative positions. Opening the HTML alone, or moving it away from the folder, breaks the images.</p><p><strong>Single-file mode:</strong> images are embedded, so only the HTML file is needed. The trade-off is size — a whole chapter may be tens of megabytes.</p><h2 id="the-original-image-cannot-be-found" tabindex="-1">The original image cannot be found <a class="header-anchor" href="#the-original-image-cannot-be-found" aria-label="Permalink to &quot;The original image cannot be found&quot;">​</a></h2><p><strong>Symptom:</strong> a <code>.mnproj</code> import reports missing images, or a page shows a 404 placeholder.</p><ul><li><strong>Reference-mode projects</strong> store paths, not images. If the images moved, import again and set a <strong>relink directory</strong>. The importer matches by SHA-1 first, then by filename, preferring folders that contain the volume and chapter names.</li><li><strong>Packaged-mode projects</strong> carry images in <code>assets/</code>. A missing asset means the package is incomplete; re-export it.</li><li>If images still exist but were renamed, put them in a folder with the expected structure and use relink.</li></ul><h2 id="my-edits-disappeared" tabindex="-1">My edits disappeared <a class="header-anchor" href="#my-edits-disappeared" aria-label="Permalink to &quot;My edits disappeared&quot;">​</a></h2><p>Check the save mode in the toolbar:</p><ul><li><strong>Auto</strong> saves with a debounce.</li><li><strong>Confirm</strong> requires clicking the save check. Leaving with unsaved changes shows a browser warning, but a crash or forced close can still lose the last edits.</li></ul><p>Also check that you are looking at the same page: the URL hash includes volume, chapter, page and view. Opening the app on another data directory shows a different library.</p><h2 id="panel-notes-vanished-after-applying-a-template" tabindex="-1">Panel notes vanished after applying a template <a class="header-anchor" href="#panel-notes-vanished-after-applying-a-template" aria-label="Permalink to &quot;Panel notes vanished after applying a template&quot;">​</a></h2><p>When a panel template (or a re-detect) changes the panel count, panel-scoped notes cannot be mapped reliably, so they are dropped. Page-scoped notes are always kept. If the count is unchanged, notes are remapped by reading order.</p><p>To avoid this, export a backup before applying a template to a whole chapter.</p><h2 id="port-5173-is-already-in-use" tabindex="-1">Port 5173 is already in use <a class="header-anchor" href="#port-5173-is-already-in-use" aria-label="Permalink to &quot;Port 5173 is already in use&quot;">​</a></h2><p>Vite is configured with <code>strictPort: false</code>, so it moves to the next free port. Read the terminal output for the actual URL. The docs site uses <code>5174</code>.</p><h2 id="how-do-i-back-up-everything" tabindex="-1">How do I back up everything? <a class="header-anchor" href="#how-do-i-back-up-everything" aria-label="Permalink to &quot;How do I back up everything?&quot;">​</a></h2><ul><li><strong>Backup ZIP</strong> — all of <code>data/</code> (JSON, templates, presets), excluding the thumbnail cache.</li><li><strong><code>.mnproj</code></strong> — project package, with or without images.</li><li><strong>Copying folders</strong> — <code>raw/</code> is your images; <code>data/</code> is your work; <code>exports/</code> is regenerable.</li></ul><p>See <a href="/KomaYomi-docs/remote-backup">Remote Storage &amp; Backup</a>.</p><h2 id="thumbnails-look-stale-or-broken" tabindex="-1">Thumbnails look stale or broken <a class="header-anchor" href="#thumbnails-look-stale-or-broken" aria-label="Permalink to &quot;Thumbnails look stale or broken&quot;">​</a></h2><p>Delete <code>data/cache/thumbs/</code>. It is a cache and is rebuilt on demand. The backup and project packages already exclude it.</p><h2 id="searching-notes-returns-nothing" tabindex="-1">Searching notes returns nothing <a class="header-anchor" href="#searching-notes-returns-nothing" aria-label="Permalink to &quot;Searching notes returns nothing&quot;">​</a></h2><ul><li>The search covers note text, tags and sources. Check the active volume/chapter/tag/source filters.</li><li>A note must be <strong>saved</strong> to be indexed. In confirm mode, unsaved edits are not yet on disk.</li><li>The overview indexes page JSON; a page that failed to save has no searchable notes.</li></ul><h2 id="the-desktop-app-starts-but-shows-an-old-page-set" tabindex="-1">The desktop app starts but shows an old page set <a class="header-anchor" href="#the-desktop-app-starts-but-shows-an-old-page-set" aria-label="Permalink to &quot;The desktop app starts but shows an old page set&quot;">​</a></h2><p>The desktop window may be using a different data directory than the repository. Check the window title (it includes the data path) and press <code>Ctrl+Shift+D</code> to switch. <code>MANGA_DATA_DIR</code> overrides the stored setting.</p><h2 id="why-can-t-i-export-pdf-or-word" tabindex="-1">Why can&#39;t I export PDF or Word? <a class="header-anchor" href="#why-can-t-i-export-pdf-or-word" aria-label="Permalink to &quot;Why can&#39;t I export PDF or Word?&quot;">​</a></h2>',41)),t("p",null,[e[0]||(e[0]=a("Only HTML and PNG are implemented. PDF, ",-1)),e[1]||(e[1]=t("code",null,".docx",-1)),e[2]||(e[2]=a(" and vocabulary lists are ",-1)),d(r,{type:"warning",text:"Planned"}),e[3]||(e[3]=a(". As a workaround, open the exported HTML in a browser and use ",-1)),e[4]||(e[4]=t("strong",null,"Print → Save as PDF",-1)),e[5]||(e[5]=a("; the HTML has print styles that break pages and avoid splitting panels or notes.",-1))]),e[7]||(e[7]=o('<h2 id="how-do-i-create-panel-groups" tabindex="-1">How do I create panel groups? <a class="header-anchor" href="#how-do-i-create-panel-groups" aria-label="Permalink to &quot;How do I create panel groups?&quot;">​</a></h2><p>Select one or more panels in the workbench and click <strong>Group</strong>. The new group appears in the <strong>Groups</strong> panel, where you can rename it, change its colour, reorder its chips, merge it upward, split it or delete it without deleting the panels. <strong>Sort by group</strong> renumbers the page by group order. Groups are preserved by page exchange files, project packages and exports; see <a href="/KomaYomi-docs/guide/panels#groups">Panel Workbench</a>. Vector <strong>annotations</strong> are implemented too: arrow, rectangle, ellipse, highlight, pen, text, badge and mosaic.</p><h2 id="does-it-send-my-data-anywhere" tabindex="-1">Does it send my data anywhere? <a class="header-anchor" href="#does-it-send-my-data-anywhere" aria-label="Permalink to &quot;Does it send my data anywhere?&quot;">​</a></h2><p>By default, no. The server listens on <code>127.0.0.1</code>, and nothing is uploaded unless you configure a remote target. Two features make outbound requests: the optional &quot;fetch page title&quot; action for a note source (requests the URL you typed, 5-second timeout), and any WebDAV / network storage target you add (image fetches and backup uploads). With no storage target configured, all data stays local.</p><h2 id="old-page-json-is-not-opening" tabindex="-1">Old page JSON is not opening <a class="header-anchor" href="#old-page-json-is-not-opening" aria-label="Permalink to &quot;Old page JSON is not opening&quot;">​</a></h2><p>Hand-edited or older JSON is normalized on read: missing ids are generated, rectangles are clamped, invalid enum values fall back to defaults, and dangling group references are dropped. If the file is not valid JSON at all, the app treats the page as having no data and will detect it again — which overwrites the file on save. Restore from a backup if that happens.</p><h2 id="something-else-is-wrong" tabindex="-1">Something else is wrong <a class="header-anchor" href="#something-else-is-wrong" aria-label="Permalink to &quot;Something else is wrong&quot;">​</a></h2><p>Collect this before asking for help:</p><ol><li>The terminal output where <code>npm run dev</code> or <code>npm run desktop</code> was started.</li><li>The exact page path (<code>data/pages/&lt;volume&gt;/&lt;chapter&gt;/&lt;index&gt;.json</code>).</li><li>Whether the problem reproduces after deleting <code>data/cache/thumbs/</code>.</li><li>The output of <code>node scripts/manga-cli.ts report</code> if the issue is detection-related.</li></ol>',9))])}const k=n(h,[["render",p]]);export{y as __pageData,k as default};
